using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Adds a new media preview to the beginning of the list of media previews of a bot. Returns the added preview after addition is completed server-side. The total number of previews must not exceed getOption("bot_media_preview_count_max") for the given language
    /// </summary>
    public Task<TdLib.TdApi.Objects.BotMediaPreview> AddBotMediaPreviewAsync(long botUserId = default, string languageCode = default, InputStoryContent content = default)
    {

           using var activity =  StartCallActivity("AddBotMediaPreviewAsync", typeof(AddBotMediaPreview).FullName ?? "AddBotMediaPreviewAsync");

           try
           {
             return client.AddBotMediaPreviewAsync(botUserId, languageCode, content);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
